            process.exit(1);
          }
          if (format !== 'markdown' && format !== 'json') {
            p.log.error('Invalid --format value. Use markdown or json.');
            process.exit(1);
          }

          await exportReviewCommand(reviewId, format, outputPath);
          break;
        }

        p.log.error('Unknown review command. Use: create, preflight, show, events, export');
        process.exit(1);
      }

      case 'admin': {
        const adminAction = positional[0];
        if (adminAction === 'provision-key') {
          const labelFlag = flags.label;
          const accountIdFlag = flags['account-id'];
          const label = typeof labelFlag === 'string' ? labelFlag : '';
          const accountId = typeof accountIdFlag === 'string' ? accountIdFlag : undefined;

          await provisionAdminKeyCommand({
            label,
            accountId,
            isAdmin: Boolean(flags.admin),
          });
          break;
        }

        p.log.error('Unknown admin command. Use: provision-key');
        process.exit(1);
      }

      case 'list': {
        await listCommand();
        break;
      }

      case 'watch': {
        const jobId = positional[0];
        if (!jobId) {
          p.log.error('Missing job ID. Usage: nimbus watch <job-id>');
          process.exit(1);
        }
        await watchCommand(jobId);
        break;
      }

      default: {
        p.log.error(`Unknown command: ${command}`);
        p.log.info('Run "nimbus --help" for usage information.');
        process.exit(1);
      }
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    p.log.error(message);
    process.exit(1);
  }
}

