            summarizeSession: (() => {
              const summarizeSessionFlag = flags['summarize-session'];
              if (typeof summarizeSessionFlag !== 'string') {
                return undefined;
              }
              if (summarizeSessionFlag === 'auto' || summarizeSessionFlag === 'always' || summarizeSessionFlag === 'never') {
                return summarizeSessionFlag;
              }
