const BUNDLE_BASE64_PART_PREFIX = '/tmp/review-source.tar.gz.base64.part';
const BUNDLE_BASE64_CHUNK_BYTES = 510 * 1024;
const DEFAULT_REVIEW_AGENT_MAX_STEPS = 6;
const DEFAULT_REVIEW_MAX_FILE_BYTES = 48_000;
