  workspaceId: string;
  deploymentId: string;
  sourceBundleKey: string;
  authoritativeDiffSnapshot?: unknown;
  goal: string;
  constraints: string[];
  decisions: string[];
  intentSessionContext: string[];
  evidenceCatalog: Array<{ id: string; type: string; label: string; status: string }>;
  deploymentSummary: {
