    for (const [key, value] of baseHeaders) {
      headers[key] = value;
    }
  } else if (baseHeaders) {
    Object.assign(headers, baseHeaders as Record<string, string>);
  }

  const openrouterApiKey = readOpenrouterApiKey();
  if (openrouterApiKey) {
    headers['X-Openrouter-Api-Key'] = openrouterApiKey;
  }
  return headers;
}

