       FROM workspace_deployments
       WHERE workspace_id = ? AND status = 'succeeded'
       ORDER BY julianday(created_at) DESC, rowid DESC
       LIMIT 1`
    )
    .bind(workspaceId)
    .first<WorkspaceDeploymentRecord>();

  if (!record) {
