    .map((item) => item.trim())
    .filter((item) => POLICY_PREFIX_PATTERN.test(item))
    .filter((item) => !/[?]\s*$/.test(item))
    .filter((item) => !POLICY_LIST_ITEM_PATTERN.test(item))
    .filter((item) => item.length <= POLICY_MAX_CHARS)
    .map((item) => redactReviewText(item) ?? '')
    .map((item) => item.trim())
    .filter(Boolean);
}

