  const result = await db
    .prepare(
      `UPDATE workspace_deployments
       SET status = 'succeeded',
           source_snapshot_sha256 = ?,
           source_bundle_key = ?,
           deployed_url = ?,
           provider_deployment_id = ?,
           result_json = ?,
           error_code = NULL,
           error_message = NULL,
           finished_at = ?,
