          `Risk focus areas: ${input.intentSummary.riskFocus.length > 0 ? JSON.stringify(input.intentSummary.riskFocus) : 'None stated'}`,
          `Constraints: ${input.intentSummary.constraints.length > 0 ? JSON.stringify(input.intentSummary.constraints) : 'None stated'}`,
        ].join('\n')
      : `Intent session context excerpts: ${JSON.stringify(input.intentSessionContext)}`,
