export async function requestWorkspaceDeploymentCancel(
  db: D1Database,
  workspaceId: string,
  deploymentId: string
): Promise<{ deployment: WorkspaceDeploymentResponse | null; updated: boolean }> {
  const now = new Date().toISOString();
  const queuedResult = await db
    .prepare(
      `UPDATE workspace_deployments
       SET status = 'cancelled',
           cancel_requested_at = COALESCE(cancel_requested_at, ?),
           finished_at = COALESCE(finished_at, ?),
           error_code = NULL,
           error_message = NULL,
           updated_at = ?
       WHERE id = ? AND workspace_id = ? AND status = 'queued'`
    )
    .bind(now, now, now, deploymentId, workspaceId)
    .run();

  const runningResult = await db
    .prepare(
      `UPDATE workspace_deployments
       SET cancel_requested_at = COALESCE(cancel_requested_at, ?),
           updated_at = ?
       WHERE id = ? AND workspace_id = ? AND status = 'running' AND cancel_requested_at IS NULL`
    )
    .bind(now, now, deploymentId, workspaceId)
    .run();

  const deployment = await getWorkspaceDeployment(db, workspaceId, deploymentId);

  return {
    deployment,
    updated: (queuedResult.meta?.changes ?? 0) > 0 || (runningResult.meta?.changes ?? 0) > 0,
  };
}

export async function appendWorkspaceDeploymentEvent(
  db: D1Database,
  input: {
    workspaceId: string;
    deploymentId: string;
    eventType: string;
    payload: unknown;
  }
): Promise<number> {
  const seqResult = await db
    .prepare(
      'UPDATE workspace_deployments SET last_event_seq = last_event_seq + 1 WHERE id = ? AND workspace_id = ? RETURNING last_event_seq'
    )
    .bind(input.deploymentId, input.workspaceId)
    .first<{ last_event_seq: number }>();

  if (!seqResult) {
    throw new Error(`Failed to allocate event sequence for workspace deployment ${input.deploymentId}`);
  }

  const seq = Number(seqResult.last_event_seq);
  await db
    .prepare(
      `INSERT INTO workspace_deployment_events (workspace_id, deployment_id, seq, event_type, payload_json)
       VALUES (?, ?, ?, ?, ?)`
    )
    .bind(input.workspaceId, input.deploymentId, seq, input.eventType, JSON.stringify(input.payload))
    .run();

  return seq;
}

export async function listWorkspaceDeploymentEvents(
  db: D1Database,
  workspaceId: string,
  deploymentId: string,
  fromExclusive = 0,
  limit = 500
): Promise<WorkspaceDeploymentEventItem[]> {
  const result = await db
    .prepare(
      `SELECT seq, event_type, payload_json, created_at
       FROM workspace_deployment_events
       WHERE workspace_id = ? AND deployment_id = ? AND seq > ?
       ORDER BY seq ASC
       LIMIT ?`
    )
    .bind(workspaceId, deploymentId, fromExclusive, limit)
    .all<WorkspaceDeploymentEventRecord>();

  return result.results.map((row) => {
    let payload: unknown;
    try {
      payload = JSON.parse(row.payload_json);
    } catch {
      payload = { raw: row.payload_json };
    }

    return {
      seq: row.seq,
      eventType: row.event_type,
      payload,
      createdAt: row.created_at,
    };
  });
}

export async function hasWorkspaceDeploymentEvent(
  db: D1Database,
  workspaceId: string,
  deploymentId: string,
  eventType: string
): Promise<boolean> {
  const record = await db
    .prepare(
      `SELECT 1
       FROM workspace_deployment_events
       WHERE workspace_id = ? AND deployment_id = ? AND event_type = ?
       LIMIT 1`
    )
    .bind(workspaceId, deploymentId, eventType)
    .first<{ '1': number }>();

  return Boolean(record);
}

export async function createReviewRun(
  db: D1Database,
  input: CreateReviewRunInput
): Promise<{ review: ReviewRunResponse; reused: boolean }> {
  const now = new Date().toISOString();
  const acceptedHashes = new Set([input.requestPayloadSha256, ...(input.requestPayloadSha256Aliases ?? [])]);
  const existingIdempotency = await db
    .prepare(
      `SELECT review_id, request_payload_sha256, expires_at
       FROM review_run_idempotency
       WHERE workspace_id = ? AND idempotency_key = ?
       LIMIT 1`
    )
    .bind(input.workspaceId, input.idempotencyKey)
    .first<{ review_id: string; request_payload_sha256: string; expires_at: string }>();

  if (existingIdempotency && existingIdempotency.expires_at > now) {
    if (!acceptedHashes.has(existingIdempotency.request_payload_sha256)) {
      throw new ReviewIdempotencyConflictError(input.idempotencyKey);
    }

    const existingReview = await getReviewRun(db, existingIdempotency.review_id);
    if (!existingReview) {
      throw new Error(`Idempotency record references missing review ${existingIdempotency.review_id}`);
    }

    return { review: existingReview, reused: true };
  }

  if (existingIdempotency && existingIdempotency.expires_at <= now) {
    await db
      .prepare('DELETE FROM review_run_idempotency WHERE workspace_id = ? AND idempotency_key = ?')
      .bind(input.workspaceId, input.idempotencyKey)
      .run();
  }

  const idempotencyWindowStart = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
  const existingReviewByKey = await db
    .prepare(
      `SELECT *
       FROM review_runs
       WHERE workspace_id = ?
         AND idempotency_key = ?
         AND julianday(created_at) >= julianday(?)
       ORDER BY created_at DESC
       LIMIT 1`
    )
    .bind(input.workspaceId, input.idempotencyKey, idempotencyWindowStart)
    .first<ReviewRunRecord>();

  if (existingReviewByKey) {
    if (!acceptedHashes.has(existingReviewByKey.request_payload_sha256)) {
      throw new ReviewIdempotencyConflictError(input.idempotencyKey);
    }

    const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
    try {
      await db
        .prepare(
          `INSERT INTO review_run_idempotency (
             id,
             workspace_id,
             idempotency_key,
             review_id,
             request_payload_sha256,
             expires_at
           )
           VALUES (?, ?, ?, ?, ?, ?)`
        )
        .bind(
          generatePrefixedId('rvid'),
          input.workspaceId,
          input.idempotencyKey,
          existingReviewByKey.id,
          input.requestPayloadSha256,
          expiresAt
        )
        .run();
    } catch (error) {
      if (!isUniqueConstraintError(error)) {
        throw error;
      }
    }

    return { review: toReviewRunResponse(existingReviewByKey), reused: true };
  }

  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
  const sanitizedRequestPayload = stripSensitiveTokenFields(input.requestPayload ?? {});
  const sanitizedProvenance = stripSensitiveTokenFields(input.provenance ?? {});
  const reviewRecord = await db
    .prepare(
      `INSERT INTO review_runs (
         id,
         workspace_id,
         deployment_id,
         target_type,
         mode,
         status,
         idempotency_key,
         request_payload_json,
         request_payload_sha256,
         account_id,
         provenance_json,
         created_at,
         updated_at
        )
       VALUES (?, ?, ?, ?, ?, 'queued', ?, ?, ?, ?, ?, ?, ?)
       RETURNING *`
    )
    .bind(
      input.id,
      input.workspaceId,
      input.deploymentId,
      input.targetType,
      input.mode,
      input.idempotencyKey,
      JSON.stringify(sanitizedRequestPayload),
      input.requestPayloadSha256,
      input.accountId ?? null,
      JSON.stringify(sanitizedProvenance),
      now,
      now
    )
    .first<ReviewRunRecord>();

  if (!reviewRecord) {
    throw new Error('Failed to create review run');
  }

  try {
    await db
      .prepare(
        `INSERT INTO review_run_idempotency (
           id,
           workspace_id,
           idempotency_key,
           review_id,
           request_payload_sha256,
           expires_at
         )
         VALUES (?, ?, ?, ?, ?, ?)`
      )
      .bind(
        generatePrefixedId('rvid'),
        input.workspaceId,
        input.idempotencyKey,
        input.id,
        input.requestPayloadSha256,
        expiresAt
      )
      .run();
  } catch (error) {
    if (!isUniqueConstraintError(error)) {
      await db.prepare('DELETE FROM review_runs WHERE id = ?').bind(input.id).run();
      throw error;
    }

    const concurrent = await db
      .prepare(
        `SELECT review_id, request_payload_sha256, expires_at
         FROM review_run_idempotency
         WHERE workspace_id = ? AND idempotency_key = ?
         LIMIT 1`
      )
      .bind(input.workspaceId, input.idempotencyKey)
      .first<{ review_id: string; request_payload_sha256: string; expires_at: string }>();

    if (!concurrent || concurrent.expires_at <= now) {
      await db.prepare('DELETE FROM review_runs WHERE id = ?').bind(input.id).run();
      throw new Error('Review idempotency race detected but winner record is unavailable');
    }

    if (!acceptedHashes.has(concurrent.request_payload_sha256)) {
      await db.prepare('DELETE FROM review_runs WHERE id = ?').bind(input.id).run();
      throw new ReviewIdempotencyConflictError(input.idempotencyKey);
    }

    const existingReview = await getReviewRun(db, concurrent.review_id);
    if (!existingReview) {
      await db.prepare('DELETE FROM review_runs WHERE id = ?').bind(input.id).run();
      throw new Error(`Idempotency record references missing review ${concurrent.review_id}`);
    }

    await db.prepare('DELETE FROM review_runs WHERE id = ?').bind(input.id).run();
    return { review: existingReview, reused: true };
  }

  return { review: toReviewRunResponse(reviewRecord), reused: false };
}

