  if (!value || typeof value !== 'object') {
    if (typeof value === 'string' && GITHUB_TOKEN_PATTERN_TEST.test(value)) {
      return value.replace(GITHUB_TOKEN_PATTERN, '[REDACTED_TOKEN]');
